"""Regenerate lucide-subset.js from the SVG files in icons/ (lucide-static v0.460.0, ISC).

To add an icon: download it once into icons/ from
  https://unpkg.com/lucide-static@0.460.0/icons/<name>.svg
then run:  python server/static/vendor/lucide/build_subset.py
"""
import json
import pathlib
import re

HERE = pathlib.Path(__file__).parent
out = {}
for f in sorted((HERE / "icons").glob("*.svg")):
    svg = f.read_text(encoding="utf-8")
    inner = re.search(r"<svg[^>]*>(.*)</svg>", svg, re.S).group(1)
    out[f.stem] = re.sub(r"\s+", " ", inner).strip()

js = ("// Generated by build_subset.py from lucide-static v0.460.0 (ISC license, see LICENSE).\n"
      "// Inner SVG markup of each icon, viewBox 0 0 24 24, stroke = currentColor.\n"
      "window.LUCIDE = " + json.dumps(out, indent=0, ensure_ascii=True) + ";\n")
(HERE / "lucide-subset.js").write_text(js, encoding="utf-8")
print(f"{len(out)} icons -> lucide-subset.js")
